[Form]
public class GUPJournalIdDialog extends FormRun
{
    public	JournalId	JournalId;
    public	String30	callerId;
    public  RetailPeriodicDiscount retailPeriodicDiscountOrig;


}

public void init()
{
    JournalId = element.args().parm();
    callerId  = element.args().callerName();

    RetailDiscountOffer discountOfferOrigin;

    if (element.args().record())
    {
        Common callerRecord = element.args().record();

        switch (callerRecord.TableId)
        {
            case tableNum(RetailDiscountOffer) :
            case tableNum(RetailDiscountMultibuy) :
            case tableNum(RetailDiscountMixAndMatch) :
            case tableNum(RetailDiscountThreshold) :
                retailPeriodicDiscountOrig = element.args().record();
                break;

            default :
                break;
        }
    }

    super();

    this.updateDesign();
    PriceIdStringControl.text(JournalId);
}

	public void updateDesign()
    {
        if (callerId == classStr(GUPVendPriceAdmTableCopy))
        {
            element.design().caption("@GlobalUnifiedPricing:GUPVendPriceAdmJournalNum");
            PriceIdStringControl.label("@GlobalUnifiedPricing:GUPVendPriceAdmJournalNum");
        }

        else if (callerId == classStr(GUPPriceTermJournalTableCopy))
        {
            element.design().caption("@GlobalUnifiedPricing:GUPAgreementId");
            PriceIdStringControl.label("@GlobalUnifiedPricing:GUPAgreementId");
        }
        else if (!callerId)
        {
            if (retailPeriodicDiscountOrig)
            {
                switch (retailPeriodicDiscountOrig.PeriodicDiscountType)
                {
                    case RetailDiscountOfferTypeBase::Promotion :
                        element.design().caption("@GlobalUnifiedPricing:GUPMarginComponentAdjustment");
                        PriceIdStringControl.label("@GlobalUnifiedPricing:GUPMarginComponentAdjustment");
                        break;

                    case RetailDiscountOfferTypeBase::DiscountOffer :
                        element.design().caption("@RET3396");
                        PriceIdStringControl.label("@RET3396");
                        break;

                    case RetailDiscountOfferTypeBase::Multibuy :
                        element.design().caption("@RET3485");
                        PriceIdStringControl.label("@RET3485");
                        break;

                    case RetailDiscountOfferTypeBase::MixAndMatch :
                        element.design().caption("@RET3480");
                        PriceIdStringControl.label("@RET3480");
                        break;

                    case RetailDiscountOfferTypeBase::Threshold :
                        element.design().caption("@REX1152");
                        PriceIdStringControl.label("@REX1152");
                        break;

                    default :
                        break;
                }
            }
        }
	}

	private void validateVendPriceAdmTable()
    {
        if (GUPVendPriceAdmTable::find(PriceIdStringControl.valueStr()))
        {
            throw Error(strFmt("@SYS153389", tableStr(GUPVendPriceAdmTable), PriceIdStringControl.valueStr()));
        }
    }

private void validatePriceTermJournalTable()
{
    if (GUPPriceTermJournalTable::find(PriceIdStringControl.valueStr()))
    {
        throw Error(strFmt("@SYS153389", tableStr(GUPPriceTermJournalTable), PriceIdStringControl.valueStr()));
    }
}

private void validateRetailPeriodicDiscount()
{
    if (RetailPeriodicDiscount::findByOfferId(PriceIdStringControl.valueStr()))
    {
        throw Error(strFmt("@SYS153389", tableStr(RetailPeriodicDiscount), PriceIdStringControl.valueStr()));
    }
}

        public void clicked()
        {
			if (callerId == classStr(GUPVendPriceAdmTableCopy))
            {
                element.validateVendPriceAdmTable();
            }
            else if (callerId == classStr(GUPPriceTermJournalTableCopy))
            {
                element.validatePriceTermJournalTable();
            }
            else if (retailPeriodicDiscountOrig.RecId)
            {
                element.validateRetailPeriodicDiscount();
            }
            element.closeOk();
        }
